/**
 * Canonical action-shot catalogue for the GDD walkthrough.
 *
 * This file is tracked. The capture pass writes the same fields plus the
 * generated file name and dimensions to ignored `gdd-captures/captures.json`.
 * `scripts/gdd-site.ts` consumes only that sidecar, so the gallery can be
 * rebuilt without rerunning Playwright.
 */

export type CaptureFlow =
  | "hub"
  | "launch"
  | "03-nerve-forest"
  | "04-muscle-effector"
  | "silicon"
  | "modes";

export type CapturePack = "hub" | "anatomy" | "silicon";
export type CaptureMode = "solo" | "co-op" | "n/a";
export type CaptureArt = "final" | "placeholder";

export interface CaptureState {
  id: string;
  title: string;
  flow: CaptureFlow;
  pack: CapturePack;
  level: string | null;
  room: string | null;
  beat: string;
  mode: CaptureMode;
  objectiveIds: readonly string[];
  conceptIds: readonly string[];
  relatedAssets: readonly string[];
  whatToNotice: string;
  art: CaptureArt;
  order: number;
  alt: string;
  docs: readonly string[];
  compareWith?: string;
  compareLabel?: string;
}

